import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { Box, Typography, Button, CircularProgress } from "@mui/material";
import { supabase } from "../supabase";

const VerifyPage = () => {
  const [status, setStatus] = useState("checking");
  const navigate = useNavigate();

  useEffect(() => {
    const verifyUser = async () => {
      console.log("Starting verification...");

      try {
        const { error } = await supabase.auth.exchangeCodeForSession();
        if (error) {
          console.error("Session exchange error:", error.message);
          setStatus("failed");
          return;
        }

        const { data: userData, error: userError } = await supabase.auth.getUser();
        if (userError || !userData?.user?.email_confirmed_at) {
          console.error("User not confirmed or fetch failed");
          setStatus("failed");
          return;
        }

        const userId = userData.user.id;
        const saved = JSON.parse(localStorage.getItem("signup_user"));
        if (saved) {
          const { name, dob, role } = saved;
          const { error: insertError } = await supabase.from("profiles").insert([
            { id: userId, name, dob, role },
          ]);
          if (insertError) console.error("Insert profile error:", insertError.message);
        }

        localStorage.removeItem("signup_user");

        setStatus("success");
        setTimeout(() => {
          navigate("/dashboard");
        }, 2000);
      } catch (err) {
        console.error("Unexpected error:", err);
        setStatus("failed");
      }
    };

    verifyUser();
  }, [navigate]);

  return (
    <Box
      sx={{
        height: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        flexDirection: "column",
        textAlign: "center",
        px: 3,
      }}
    >
      {status === "checking" && (
        <>
          <CircularProgress sx={{ color: "#8E2839", mb: 2 }} />
          <Typography variant="h6" color="#8E2839">
            Verifying your account...
          </Typography>
        </>
      )}

      {status === "success" && (
        <>
          <Typography variant="h6" color="green" mb={1}>
            ✅ Verification successful!
          </Typography>
          <Typography>Redirecting to your dashboard...</Typography>
        </>
      )}

      {status === "failed" && (
        <>
          <Typography variant="h6" color="red" mb={1}>
            ❌ Verification failed
          </Typography>
          <Typography mb={2}>
            Make sure you clicked the link in the same browser where you signed up.
          </Typography>
          <Button
            variant="contained"
            sx={{ backgroundColor: "#8E2839" }}
            onClick={() => navigate("/signin")}
          >
            Back to Sign In
          </Button>
        </>
      )}
    </Box>
  );
};

export default VerifyPage;
